import {areas,questions,asksSignals} from '../teste/questions.js';
import {labelFor} from '../teste/engine.js';
const root=document.querySelector('#app'),dialog=document.querySelector('#detail');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={in_progress:'Em andamento',completed:'Concluído, sem contato',profile_generated:'Perfil liberado'};
const number=n=>new Intl.NumberFormat('pt-BR').format(n);
const percent=n=>n===null?'—':new Intl.NumberFormat('pt-BR',{style:'percent',maximumFractionDigits:1}).format(n);
const date=s=>s?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(s)):'—';
let view='dashboard',page=1,filters={from:'',to:'',area:'',status:'',source:'',search:''},data=null,sequence=0,refreshTimer;
async function api(path,method='GET',body){
  const res=await fetch(`/api/admin/${path}`,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});
  const result=await res.json();if(!res.ok){if(res.status===401&&path!=='login'){clearInterval(refreshTimer);dialog.close();await start();}throw new Error(result.error||'Não foi possível carregar os dados.');}return result;
}
function auth(needsSetup){
  root.innerHTML=`<main class="auth" id="content"><a class="brand" href="../teste/">◔ <span>ROMPA<small>ÁREA ADMINISTRATIVA</small></span></a><div class="auth-card"><p class="eyebrow">${needsSetup?'PRIMEIRO ACESSO':'ACESSO RESTRITO'}</p><h1>${needsSetup?'Configure o administrador':'Bem-vindo de volta.'}</h1><p>${needsSetup?'Crie o acesso que será usado para consultar os questionários e indicadores deste ambiente local.':'Entre para acompanhar os questionários e os indicadores do ROMPA.'}</p><form id="auth-form"><label for="email">Email</label><input id="email" type="email" autocomplete="username" required maxlength="254"><label for="password">Senha ${needsSetup?'(mínimo de 12 caracteres)':''}</label><input id="password" type="password" autocomplete="${needsSetup?'new-password':'current-password'}" required minlength="${needsSetup?12:1}" maxlength="128">${needsSetup?'<label for="confirm">Confirme a senha</label><input id="confirm" type="password" autocomplete="new-password" required minlength="12" maxlength="128">':''}<p id="auth-error" class="error" role="alert"></p><button class="primary" type="submit">${needsSetup?'Criar acesso administrativo':'Entrar na administração'} <span>→</span></button></form></div><p class="auth-note">Servidor local · acesso protegido por senha<br>O teste dos participantes continua sem login.</p></main>`;
  root.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),error=root.querySelector('#auth-error');error.textContent='';const password=root.querySelector('#password').value;if(needsSetup&&password!==root.querySelector('#confirm').value){error.textContent='As senhas não conferem.';return;}button.disabled=true;
    try{await api(needsSetup?'setup':'login','POST',{email:root.querySelector('#email').value,password});shell();await load();}catch(e){error.textContent=e.message;}finally{button.disabled=false;}
  };
}
function shell(){
  root.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="./">◔ <span>ROMPA<small>ADMINISTRAÇÃO</small></span></a><p class="nav-label">GESTÃO DO TESTE</p><nav aria-label="Administração"><button data-view="dashboard">▦ <span>Visão geral</span></button><button data-view="records">☷ <span>Questionários</span></button><button data-view="insights">◴ <span>Indicadores</span></button></nav><div class="sidebar-bottom"><a href="../teste/" target="_blank" rel="noopener">Abrir teste ↗</a><button id="logout">Sair da conta ↗</button><span class="local-dot">Ambiente local</span></div></aside><div class="workspace"><header class="topbar"><span>TESTE DOS PADRÕES <span class="divider">/</span> <span id="breadcrumb">Visão geral</span></span><span class="private-tag">Acesso administrativo</span></header><main id="content"><div class="page-title"><div><p class="eyebrow">ROMPA · TESTE DOS PADRÕES</p><h1 id="page-title">Visão geral</h1><p id="page-description">Da primeira resposta ao próximo avanço.</p></div><button class="secondary" id="refresh">↻ Atualizar</button></div><form id="filters" class="filters"><label>De<input name="from" type="date" aria-label="Data inicial"></label><label>Até<input name="to" type="date" aria-label="Data final"></label><label>Área<select name="area"><option value="">Todas as áreas</option>${areas.map(a=>`<option value="${a.value}">${esc(a.label)}</option>`).join('')}</select></label><label>Status<select name="status"><option value="">Todos os status</option>${Object.entries(statuses).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label>Origem<select name="source"><option value="">Todas as origens</option></select></label><label class="search-label">Buscar participante<input name="search" type="search" placeholder="Nome, contato ou ID" maxlength="254"></label><button type="submit" class="primary compact">Aplicar filtros</button><button type="button" id="clear" class="text-button">Limpar</button></form><p id="scope" class="scope">Carregando registros…</p><p id="error" class="error" role="alert"></p><div id="dashboard" aria-live="polite"></div><footer class="admin-footer"><span>Fonte: questionários autorizados e salvos neste servidor.</span><span id="updated"></span></footer></main></div></div>`;
  root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;paint();});
  root.querySelector('#filters').onsubmit=e=>{e.preventDefault();filters=Object.fromEntries(new FormData(e.target));page=1;load();};
  root.querySelector('#clear').onclick=()=>{root.querySelector('#filters').reset();filters={};page=1;load();};
  root.querySelector('#refresh').onclick=()=>load();
  root.querySelector('#logout').onclick=async()=>{try{await api('logout','POST',{});data=null;clearInterval(refreshTimer);auth(false);}catch(e){root.querySelector('#error').textContent=e.message;}};
  clearInterval(refreshTimer);refreshTimer=setInterval(()=>{if(!document.hidden&&!dialog.open)load(true);},30000);
}
async function load(quiet=false){
  const request=++sequence,button=root.querySelector('#refresh');if(!button)return;button.disabled=true;
  try{const result=await api('query','POST',{filters,page});if(request!==sequence)return;data=result;page=data.page;root.querySelector('#error').textContent='';const select=root.querySelector('[name=source]');select.innerHTML='<option value="">Todas as origens</option>'+data.sources.map(source=>`<option value="${esc(source)}">${esc(source)}</option>`).join('');select.value=filters.source||'';paint();}
  catch(e){const error=root.querySelector('#error');if(error)error.textContent=`${e.message} ${data?'Os dados exibidos são da última atualização concluída.':''}`;}
  finally{if(request===sequence)button.disabled=false;}
}
function card(label,value,note){return `<article class="kpi"><p>${label}</p><strong>${value}</strong><small>${note}</small></article>`;}
function bars(title,distribution,note=''){
  const max=Math.max(1,...distribution.items.map(x=>x.value));
  return `<section class="panel"><div class="panel-heading"><h2>${title}</h2><span>${number(distribution.answered)} respostas</span></div>${distribution.answered?`<ul class="bars">${distribution.items.map(x=>`<li><div><span>${esc(x.label)}</span><b>${number(x.value)}</b></div><progress value="${x.value}" max="${max}" aria-label="${esc(x.label)}: ${x.value}"></progress></li>`).join('')}</ul>`:'<p class="empty-chart">Ainda não há respostas para este indicador.</p>'}${note?`<p class="chart-note">${note}</p>`:''}</section>`;
}
function records(){return `<section class="panel records"><div class="panel-heading"><h2>Questionários <span class="count">${number(data.total)}</span></h2><span>Mais recentes primeiro</span></div>${data.records.length?`<div class="table-scroll"><table><thead><tr><th>Participante / início</th><th>Área principal</th><th>Status</th><th>Respostas</th><th>Origem</th><th><span class="sr-only">Consultar</span></th></tr></thead><tbody>${data.records.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${date(r.created_at)}</small></td><td>${esc(r.area)}</td><td><span class="status ${r.status}">${statuses[r.status]}</span></td><td>${r.answered} / ${r.total}</td><td>${esc(r.source)}</td><td><button class="row-link" data-detail="${r.id}" aria-label="Ver questionário de ${esc(r.name)}">Ver respostas ↗</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${(data.page-1)*15+1}–${Math.min(data.page*15,data.total)} de ${number(data.total)}</span><div><button class="secondary" id="prev" ${data.page<=1?'disabled':''}>← Anterior</button><span>Página ${data.page} de ${Math.ceil(data.total/15)}</span><button class="secondary" id="next" ${data.page*15>=data.total?'disabled':''}>Próxima →</button></div></div>`:'<div class="empty"><span class="empty-icon">☷</span><h3>Nenhum questionário encontrado</h3><p>Os testes aparecem aqui após a autorização do participante e o salvamento no servidor. Você também pode ajustar os filtros.</p><a class="secondary" href="../teste/" target="_blank" rel="noopener">Abrir o teste ↗</a></div>'}</section>`;}
function paint(){
  if(!data)return;const m=data.metrics;
  const titles={dashboard:['Visão geral','Da primeira resposta ao próximo avanço.'],records:['Questionários','Consulte respostas, contatos, consentimentos e o perfil de cada participante.'],insights:['Indicadores','Entenda as áreas, os contextos e os momentos declarados pelos participantes.']};
  root.querySelector('#page-title').textContent=titles[view][0];root.querySelector('#breadcrumb').textContent=titles[view][0];root.querySelector('#page-description').textContent=titles[view][1];
  root.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});
  root.querySelector('#scope').textContent=`${number(data.total)} questionário(s) no recorte · período pela data de início · horário de Brasília · filtros aplicados a todos os indicadores.`;
  root.querySelector('#updated').textContent=`Atualizado em ${date(data.updatedAt)} · atualização a cada 30 s`;
  let html='';
  if(view==='dashboard'){
    html=`<div class="kpis">${card('Questionários iniciados',number(m.total),`${number(m.inProgress)} em andamento`)}${card('Taxa de conclusão',percent(m.completionRate),`${number(m.completed)} concluídos / ${number(m.total)} iniciados`)}${card('Contatos capturados',number(m.leads),`${percent(m.captureRate)} dos concluídos`)}${card('Perfis visualizados',number(m.profiles),'Participantes distintos no recorte')}</div><div class="chart-grid"><section class="panel"><div class="panel-heading"><h2>Funil do teste</h2><span>Questionários únicos</span></div>${m.total?`<ol class="funnel">${m.funnel.map((r,i)=>`<li><div><span><i>0${i+1}</i>${r.label}</span><strong>${number(r.value)} <small>${percent(r.value/m.total)}</small></strong></div><progress value="${r.value}" max="${m.total}" aria-label="${r.label}: ${r.value}"></progress></li>`).join('')}</ol>`:'<p class="empty-chart">O funil será formado conforme os testes forem salvos.</p>'}<p class="chart-note">Base: testes autorizados. Conclusão conta quem chegou ao fim ao menos uma vez. Vendas não são medidas: o checkout ainda não está integrado.</p></section>${bars('Áreas mais relatadas',m.areas,'Contagem por área principal; respostas abertas de “Outra área” ficam nos questionários.')}</div><div class="chart-grid">${bars('Momento da percepção',m.moments)}<section class="panel"><div class="panel-heading"><h2>Inícios por dia</h2><span>Coortes de início</span></div>${m.daily.length?`<div class="daily-scroll"><table class="daily"><thead><tr><th>Dia</th><th>Iniciados</th><th>Concluíram</th><th>Contatos</th></tr></thead><tbody>${m.daily.map(r=>`<tr><td>${r.date.split('-').reverse().join('/')}</td><td><progress max="${Math.max(1,...m.daily.map(x=>x.started))}" value="${r.started}" aria-label="${r.started} iniciados"></progress> ${r.started}</td><td>${r.completed}</td><td>${r.leads}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-chart">O histórico começa com o primeiro questionário salvo.</p>'}<p class="chart-note">Conclusões e contatos pertencem à data de início do teste, não ao dia em que a pessoa concluiu.</p></section></div>${records()}`;
  }else if(view==='records')html=records();
  else html=`<div class="kpis three">${card('Reconhecimento do resultado',percent(m.adherence),`“Sim, muito bem” / ${number(m.feedbackCount)} avaliações`)}${card('Avaliações recebidas',number(m.feedbackCount),'Uma avaliação atual por questionário')}${card('Cliques no ebook',number(m.clicks),'Questionários com clique; não são compras')}</div><div class="chart-grid">${bars('Aderência percebida',m.feedback,'Feedback de reconhecimento, sem validade diagnóstica.')}${bars('Frequência percebida',m.frequency)}${bars('Gatilhos relatados',m.triggers,'Seleção múltipla: até três escolhas por resposta. As contagens não devem ser somadas como pessoas.')}${bars('Consequências relatadas',m.consequences,'Seleção múltipla: até três escolhas por resposta.')}${bars('Capacidade de pausa',m.pause)}${bars('Soluções já tentadas',m.solutions,'Seleção múltipla. Uma pessoa pode aparecer em várias alternativas.')}${bars('Origem dos questionários',{answered:m.total,items:m.sources},'UTM source registrada no início do teste.')}${bars('Momento da percepção',m.moments)}</div>`;
  root.querySelector('#dashboard').innerHTML=html;
  root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));
  root.querySelector('#prev')?.addEventListener('click',()=>{page--;load();});root.querySelector('#next')?.addEventListener('click',()=>{page++;load();});
}
function valueFor(q,a){
  if(q.id==='Q08'&&!asksSignals(a))return 'Não exibida pela resposta sobre percepção de sinais.';
  if(a[q.key]===undefined)return 'Não respondida';
  if(q.type==='text')return a[q.key];
  return (Array.isArray(a[q.key])?a[q.key]:[a[q.key]]).map(v=>labelFor(q.key,v,a)).join(' · ');
}
async function detail(id){
  dialog.innerHTML='<p role="status">Carregando questionário…</p>';dialog.showModal();
  try{const r=await api(`assessments/${id}`),a=r.data.answers,u=r.data.user;
    dialog.innerHTML=`<div class="dialog-head"><div><p class="eyebrow">QUESTIONÁRIO</p><h2 id="detail-title">${esc(u?.first_name||'Participante sem contato')}</h2></div><button id="close-detail" class="secondary" aria-label="Fechar detalhes">✕</button></div><div class="dialog-body"><div class="record-meta"><span class="status ${r.status}">${statuses[r.status]}</span><p>Início: ${date(r.created_at)}<br>Último salvamento: ${date(r.updated_at)}<br><small>ID: ${esc(r.id)}</small></p></div><section><h3>Contato e autorizações</h3>${u?`<dl class="facts"><dt>WhatsApp</dt><dd>${esc(u.whatsapp)}</dd><dt>Email</dt><dd>${esc(u.email||'Não informado')}</dd><dt>Marketing</dt><dd>${u.marketing_consent?'Autorizado':'Não autorizado'}</dd><dt>Contato autorizado em</dt><dd>${date(u.consented_at)}</dd><dt>Versão de privacidade</dt><dd>${esc(u.privacy_version)}</dd></dl>`:'<p>A pessoa ainda não informou contato. As respostas salvas continuam disponíveis abaixo.</p>'}<p class="muted">Armazenamento autorizado em ${date(r.data.storage_consent.accepted_at)} · ${esc(r.data.storage_consent.version)}</p></section><section><h3>Origem</h3><dl class="facts">${['utm_source','utm_medium','utm_campaign','utm_content','referrer','device'].map(key=>`<dt>${key.replace('utm_','')}</dt><dd>${esc(r.data.session[key]||'Não informado')}</dd>`).join('')}</dl></section><section><h3>Respostas do questionário</h3><ol class="answers">${questions.map(q=>`<li><small>${q.id}</small><h4>${esc(q.title)}</h4><p>${esc(valueFor(q,a))}</p>${a[`${q.key}_detalhe`]?`<p class="muted">Complemento: ${esc(a[`${q.key}_detalhe`])}</p>`:''}</li>`).join('')}</ol></section>${r.data.profile?`<section class="profile-summary"><h3>Perfil gerado</h3><blockquote>${esc(r.data.profile.pattern)}</blockquote><p>${esc(r.data.profile.momentCopy)}</p><p><b>Foco:</b> ${esc(r.data.profile.priority)}</p><p><b>Resultado desejado:</b> ${esc(r.data.profile.desire)}</p><p class="muted">Motor determinístico, baseado nas respostas declaradas.</p></section>`:''}<section><h3>Aderência percebida</h3><p>${esc(['Sim, muito bem','Em parte','Não muito'][r.data.feedback]||'Ainda não avaliado')}</p></section><details><summary>Eventos registrados (${r.data.events.length})</summary><ol class="events">${r.data.events.map(e=>`<li><span>${esc(e.event_name)}</span><small>${esc(e.created_at)}</small></li>`).join('')}</ol></details><p class="error" id="detail-error" role="alert"></p><button class="danger" id="delete-record">Excluir este questionário</button><p class="muted">Exclui respostas e contato do banco ativo. Esta ação não pode ser desfeita pela aplicação.</p></div>`;
    dialog.querySelector('#close-detail').onclick=()=>dialog.close();
    dialog.querySelector('#delete-record').onclick=async()=>{if(!confirm('Excluir definitivamente as respostas e o contato deste questionário?'))return;try{await api(`assessments/${id}`,'DELETE',{});dialog.close();await load();}catch(e){dialog.querySelector('#detail-error').textContent=e.message;}};
  }catch(e){dialog.innerHTML=`<h2 id="detail-title">Não foi possível abrir</h2><p class="error">${esc(e.message)}</p><button class="secondary" id="close-detail">Fechar</button>`;dialog.querySelector('#close-detail').onclick=()=>dialog.close();}
}
async function start(){try{const session=await api('session');if(session.authenticated){shell();await load();}else auth(session.needsSetup);}catch(e){root.innerHTML=`<main class="auth"><h1>Servidor indisponível</h1><p>${esc(e.message)}</p><button class="primary" id="retry">Tentar novamente</button></main>`;root.querySelector('#retry').onclick=start;}}
start();
